from PIL import Image
import numpy as np, subprocess, sys

def _ocr_white(im, box, whitelist='0123456789'):
    c=im.crop(box).convert('RGB')
    c=c.resize((c.width*8,c.height*8),Image.LANCZOS)
    a=np.array(c).astype(np.int32)
    R,G,B=a[...,0],a[...,1],a[...,2]
    mask=(R>170)&(G>170)&(B>160)
    if mask.sum()<20: 
        # relax
        mask=(R>140)&(G>140)&(B>130)
    b=np.where(mask,0,255).astype('uint8')  # black text on white
    Image.fromarray(b).save('/tmp/n.png')
    r=subprocess.run(['tesseract','/tmp/n.png','stdout','--psm','7','-c','tessedit_char_whitelist='+whitelist],capture_output=True,text=True)
    return r.stdout.strip().replace(' ','')

def read_scores(im):
    return _ocr_white(im,(570,4,613,23)), _ocr_white(im,(667,4,711,23))
def read_clock(im):
    return _ocr_white(im,(607,15,663,32),'0123456789:')

if __name__=='__main__':
    for p in sys.argv[1:]:
        im=Image.open(p); print(p,'scores',read_scores(im),'clock',read_clock(im))
